   "evidence": "Dependency map update: the ledger needs the auth gateway (service tokens)"
  }
 ],
 "add_relations": [
  {
   "src": "Ledger",
   "dst": "authentication gateway",
   "rel_kind": "depends_on",
   "evidence": "the ledger needs the auth gateway (service tokens)"
  }
 ],
 "entity_aliases": [
  {
   "name": "auth gateway",
   "canonical": "authentication gateway",
   "evidence": "the ledger needs the auth gateway (service tokens)"
  }
 ]
}

